import re, pathlib, sys
N=19
files=sorted(pathlib.Path('outputs').glob('problem-*.sgf'))
prop_re=re.compile(r'([A-Za-z]+)((?:\\[["'^'"\\]]*\\])+)' )
vals_re=re.compile(r'\\[(["'^'"\\]]*)\\]')

def tokenize(s):
    toks=[]; i=0
    while i<len(s):
        c=s[i]
        if c in '();': toks.append(c); i+=1
        elif c.isspace(): i+=1
        elif c.isalpha():
            j=i
            while j<len(s) and s[j].isalpha(): j+=1
            ident=s[i:j]
            vals=[]
            while j<len(s) and s[j]=='[':
                j+=1; val=[]
                while j<len(s):
                    if s[j]=='\\\\' and j+1<len(s):
                        val.append(s[j+1]); j+=2
                    elif s[j]==']':
                        j+=1; break
                    else:
                        val.append(s[j]); j+=1
                vals.append(''.join(val))
            toks.append((ident,vals)); i=j
        else:
            raise ValueError(f'unexpected char {c"'!r} at {i}'"')
    return toks

class Node:
    def __init__(self): self.props=[]; self.children=[]

def parse(s):
    toks=tokenize(s); i=0
    def parse_tree(i):
        assert toks[i]=='('; i+=1
        prev=None; first=None
        while i<len(toks):
            if toks[i]==';':
                i+=1; n=Node()
                while i<len(toks) and isinstance(toks[i],tuple):
                    n.props.append(toks[i]); i+=1
                if prev is None: first=n
                else: prev.children.append(n)
                prev=n
            elif toks[i]=='(':
                child,i=parse_tree(i)
                prev.children.append(child)
            elif toks[i]==')':
                return first,i+1
            else:
                raise ValueError(f'bad tok {toks[i]}')
        raise ValueError('unclosed')
    root,i=parse_tree(0)
    if i"'!=len(toks): raise ValueError('"'trailing')
    return root

def coords(pt):
    if len(pt)"'!=2: raise ValueError(f'"'bad coord {pt"'!r}'"')
    x=ord(pt[0])-97; y=ord(pt[1])-97
    if not (0<=x<N and 0<=y<N): raise ValueError(f'offboard {pt}')
    return x,y

def neigh(p):
    x,y=p
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
        q=(x+dx,y+dy)
        if 0<=q[0]<N and 0<=q[1]<N: yield q

def group(board,p):
    col=board[p]; seen={p}; stack=[p]
    while stack:
        r=stack.pop()
        for q in neigh(r):
            if board.get(q)==col and q not in seen:
                seen.add(q); stack.append(q)
    return seen

def libs(board,g):
    return {q for p in g for q in neigh(p) if q not in board}

def play(board,col,p):
    if p in board: raise ValueError(f'occupied {p}')
    b=board.copy(); b[p]=col
    opp='W' if col=='B' else 'B'
    captured=[]
    for q in list(neigh(p)):
        if b.get(q)==opp:
            g=group(b,q)
            if not libs(b,g):
                captured+=list(g)
                for r in g: del b[r]
    g=group(b,p)
    if not libs(b,g): raise ValueError(f'suicide {col}{p}')
    return b,captured

def propsdict(n):
    d={}
    for k,v in n.props: d.setdefault(k,[]).extend(v)
    return d

for path in files:
    s=path.read_text()
    try:
        root=parse(s)
        pd=propsdict(root)
        errs=[]
        if 'SZ' not in pd or pd['SZ']"'!=['"'19']: errs.append('bad SZ')
        if 'C' in pd: errs.append('root comment')
        if 'B' in pd or 'W' in pd: errs.append('root move')
        if 'AB' not in pd or 'AW' not in pd: errs.append('missing setup color')
        board={}
        for colkey,col in [('AB','B'),('AW','W')]:
            for val in pd.get(colkey,[]):
                p=coords(val)
                if p in board: errs.append(f'duplicate setup {val}')
                board[p]=col
        for p,c in list(board.items()):
            g=group(board,p)
            if not libs(board,g): errs.append(f'zero-lib setup group {c}{p}')
        first=[]; maxdepth=0; nodes=0; rights=0
        def rec(n,b,nextcol,depth):
            nonlocal_errs=[]
            nonlocal maxdepth,nodes,rights
            for ch in n.children:
                pd2=propsdict(ch)
                moves=[k for k in ['B','W'] if k in pd2]
                if len(moves)"'!=1 or len(pd2[moves[0]])!=1:
                    errs.append(f'"'{path.name}: node not exactly one move at depth {depth+1}: {pd2}')
                    continue
                col=moves[0]; val=pd2[col][0]
                if nextcol and col"'!=nextcol: errs.append(f'"'alternation expected {nextcol} got {col}{val}')
                try:
                    p=coords(val); b2,caps=play(b,col,p)
                except Exception as e:
                    errs.append(f'illegal {col}[{val}] depth {depth+1}: {e}')
                    b2=b.copy()
                if depth==0: first.append(col)
                nodes+=1; maxdepth=max(maxdepth,depth+1)
                if any('RIGHT' in c for c in pd2.get('C',[])): rights+=1
                rec(ch,b2,'W' if col=='B' else 'B',depth+1)
        rec(root,board,None,0)
        if len(set(first))>1: errs.append(f'mixed first colors {first}')
        if maxdepth>14: errs.append(f'maxdepth {maxdepth}')
        if nodes>120: errs.append(f'nodes {nodes}')
        if rights<1: errs.append('no RIGHT')
        print(path.name, 'nodes',nodes,'maxdepth',maxdepth,'RIGHT',rights,'first',first[:1], 'ERRS' if errs else 'OK')
        for e in errs: print('  ',e)
    except Exception as e:
        print(path.name,'PARSEERR',e)
